window.STORY_CHAPTERS["c7403a9c9b0db2c98"]={"id":"c7403a9c9b0db2c98","lines":[{"uid":"talk.vc.home_silica_sao_christmas_wait_2#originalText","id":"talk.vc.home_silica_sao_christmas_wait_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"圣诞节果然是要吃蛋糕。","en":"Nothing says Christmas like a piece of cake!","ja":"クリスマスはやっぱりケーキです"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_sao_christmas_wait_3#originalText","id":"talk.vc.home_silica_sao_christmas_wait_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"圣诞快乐♪","en":"Merry Christmas♪","ja":"メリー・クリスマス♪"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_sao_christmas_wait_4#originalText","id":"talk.vc.home_silica_sao_christmas_wait_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"圣诞节和恋人约会，总觉得很浪漫，很让人憧憬。","en":"You know, going on a date with the love of your life on Christmas is pretty romantic, don't you think?","ja":"クリスマスに恋人とデートとかなんだかロマンチックで憧れちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_sao_christmas_wait_5#originalText","id":"talk.vc.home_silica_sao_christmas_wait_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算只有一点点也好，如果你觉得我可爱我会很开心……啊！嗯，没事……","en":"I would be so happy if you thought I was cute... W-Wait! Never mind...","ja":"かわいいって、少しでも思ってくれたら嬉しいな……あっ! えっと、なんでもないです……"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_sao_christmas_wait_6#originalText","id":"talk.vc.home_silica_sao_christmas_wait_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那个……可以跟你……牵手吗……？要是走散了就不好了……！","en":"C-Could we... hold hands...? I-It's so we don't lose track of each other!","ja":"あの……手を……繋いでもいいですか……?は、はぐれちゃうといけないので…!"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_valentine_wait_1#originalText","id":"talk.vc.home_silica_alo_valentine_wait_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"这是我很用心做的点心，你能收下它吗？","en":"I made this cake with all my heart. Will you accept it?","ja":"心を込めて作ったお菓子受け取ってもらえますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_valentine_wait_2#originalText","id":"talk.vc.home_silica_alo_valentine_wait_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你喜欢吃什么点心？我想要当作明年的参考，请你告诉我吧！","en":"What kind of cakes do you like? I want to take notes for next year, so please tell me!","ja":"どんなお菓子が好きですか?来年の参考にしたいので教えてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_valentine_wait_3#originalText","id":"talk.vc.home_silica_alo_valentine_wait_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那、那个……今后也请让我待在你的身旁吧。只是这样，我就已经很幸福了。","en":"P-please...from now on, let me stay by your side like this. That's all I need to be happy!","ja":"あ、あの……これからもこうやって傍に居させてくださいそれだけで、あたし幸せです"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_swim_wait_1#originalText","id":"talk.vc.home_silica_alo_swim_wait_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我、我的泳衣……会不会很孩子气……啊？","en":"D-Do you think this swimsuit makes me look like a child?","ja":"あ、あたしの水着……子どもっぽい……ですかね?"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_swim_touch_1#originalText","id":"talk.vc.home_silica_alo_swim_touch_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我已经感到很害羞了，不要一直盯着我看……","en":"D-Don't look at me like that... I'm getting embarrassed...","ja":"恥ずかしいからそんなに見ないでください……"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_alo_swim_touch_2#originalText","id":"talk.vc.home_silica_alo_swim_touch_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呀啊！那、那里！不可以摸那里！","en":"Ahhh! Hey, don't touch that!","ja":"ひゃっ!そ、そこは触っちゃダメです!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1st_1#originalText","id":"talk.vc.home_wait_silica_1st_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我经常会梦到呢。梦见我们一起救毕娜的那个山丘……","en":"I often dream about it... About that hill where we saved Pina.","ja":"よく夢に見るんですふたりでピナを助けたあの丘の夢を……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1st_2#originalText","id":"talk.vc.home_wait_silica_1st_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如果我也是你的学姊或学妹就好了……我常会这么想呢。","en":"I sometimes think it would be great if we had something like a mentor-trainee relationship.","ja":"あたしも、先輩とか後輩とかそういう関係だったらいいな……なんて、思っちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1st_3#originalText","id":"talk.vc.home_wait_silica_1st_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"用短剑战斗，必须非常贴近敌人才行……下次请教我战斗的方法吧！","en":"Since I use a dagger, I have to get awfully close when I fight... Please help me improve!","ja":"短剣で戦うには、敵にすごく接近しなくちゃいけなくて……今度戦い方を教えてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1st_4#originalText","id":"talk.vc.home_wait_silica_1st_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"前阵子，我有跟莉兹姊姊一起去逛街买东西。下次我们一起去好吗？","en":"Liz and I went shopping the other day. Would you like to come with us next time?","ja":"この間、リズさんとふたりでショッピングに行ったんです今度は一緒に行きませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1st_9#originalText","id":"talk.vc.home_wait_silica_1st_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不行，毕娜！不可以戳正在想事情的人啦！","en":"Pina! Bad dragon! Don't peck at people when they're trying to think!","ja":"こら、ピナ!考え事している人を突っついたらダメだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1st_1#originalText","id":"talk.vc.home_touch_silica_1st_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"被这样摸头，会不禁想起我们相遇的那晚……","en":"You patting my head reminds me of the night we met...","ja":"頭を撫でてもらうと最初に会った夜を思い出しちゃいます……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1st_2#originalText","id":"talk.vc.home_touch_silica_1st_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那、那个……你觉得绑双马尾的女孩子……怎么样呢？","en":"S-So... Do you like a girl in pigtails?","ja":"あ、あの……ツインテールの女の子ってどう……思いますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1st_4#originalText","id":"talk.vc.home_touch_silica_1st_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"要、要跟我组队吗？我非常乐意！","en":"Oh! Would you like to form a party with me? I'd love to have you!","ja":"あっ、あたしとパーティ組みますか?こっちは大歓迎です!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1st_5#originalText","id":"talk.vc.home_touch_silica_1st_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你、你这样对女孩子……会害人家心跳加速喔……","en":"J-Just so you know, girls get very, um...excited... when you do things like that.","ja":"お、女の子は、そういうことされると……ドキドキしちゃうんですよ……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1st_6#originalText","id":"talk.vc.home_touch_silica_1st_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"毕、毕娜在看……那个……现在不行……","en":"N-Not now... Pina is watching...","ja":"ぴ、ピナが見てますから……あの……今はそういうのは……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_1st_1#originalText","id":"talk.vc.home_time_silica_1st_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"看见晨露，就让我想起《灵魂之花》的水珠。闪闪发光的，好漂亮……","en":"Seeing the morning dew reminds me of the drops from the Pneuma Flower. Pretty, just like glitter.","ja":"朝露を見ると、《プネウマの花》の雫を思い出すんですキラキラして、キレイで……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_1st_4#originalText","id":"talk.vc.home_time_silica_1st_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"哇！你的便当看起来好好吃喔。我是不是也该提升料理技能呢……","en":"Ooh, that lunch looks delicious! Maybe I should increase my cooking skill, too.","ja":"うわあ、おいしそうなお弁当あたしも、料理スキルを高めようかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_1st_7#originalText","id":"talk.vc.home_time_silica_1st_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"当初被你救的时候，也是像这样的夜晚呢。那时候真的非常帅气！","en":"It was a night like this the first time you rescued me, huh. You were so cool!","ja":"最初にあなたが助けてくれたのも、こういう夜でしたねすごく、かっこよかったです!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_1st_10#originalText","id":"talk.vc.home_time_silica_1st_10","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呵呵，你真是夜猫子呢。不过我也没资格说别人就是了……","en":"Haha, guess you stayed up all night. Then again, I'm not one to talk.","ja":"ふふ、夜更かしさんですねあたしも、人のことを言えないですけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_1st_1#originalText","id":"talk.vc.home_day_silica_1st_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"正因为是星期一才该打起精神起床，不然整个礼拜都会提不起劲的。","en":"You have to try extra hard to get up early on Mondays. Otherwise, you'll be lazy all week.","ja":"月曜日こそ、元気に起きないと一週間ずっとダラダラしちゃうんです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_1st_2#originalText","id":"talk.vc.home_day_silica_1st_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算上学，只要能见到你，就觉得能过得很开心。","en":"I think school would be much more fun if you were there.","ja":"学校でも、あなたに会えたら楽しく過ごせると思うんです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_1st_3#originalText","id":"talk.vc.home_day_silica_1st_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"假日决定好要做什么了吗？如、如果方便的话，要不要跟我……","en":"Any plans for your day off? W-We could always hang out, if you want...","ja":"お休みの予定は決まっているんですか?よ、よかったらあたしと……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_1st_4#originalText","id":"talk.vc.home_day_silica_1st_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呼啊……今天也玩得很尽兴，我已经觉得有点困了。","en":"Wooo... I played so hard today I feel really sleepy now.","ja":"ふわあ……今日はたくさん遊んだから、なんだかもう眠くなっちゃいました"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_1st_1#originalText","id":"talk.vc.home_season_silica_1st_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"春天下的雨，总给人很温柔的感觉呢。声音听起来也觉得很宁静。","en":"Spring rain is really soothing somehow. I love how quiet the pitter-patter is.","ja":"春の雨って、なんだか優しいですよね音も静かな感じがします"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_1st_2#originalText","id":"talk.vc.home_season_silica_1st_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"海水浴场虽然很好玩，但一起去的大家身材都好好喔……","en":"Beaches are fun, but I always feel insecure seeing all the sleek beach bodies...","ja":"海水浴は楽しいけど一緒に行くみんなはスタイルがいいから……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_1st_3#originalText","id":"talk.vc.home_season_silica_1st_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"落叶成堆就会让人想要生起篝火呢。篝火很暖和喔！","en":"Collecting fallen leaves makes me want to have a bonfire. Bonfires sure are fun!","ja":"落ち葉が積もってるとたき火をしたくなります暖かいですよね、たき火!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_1st_4#originalText","id":"talk.vc.home_season_silica_1st_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"莉兹姊姊煮了火锅……方便的话，要不要一起吃呢？","en":"Liz cooked a stew, so... Want to come eat with us?","ja":"リズさんがお鍋を作ってくれて……よかったら一緒に食べませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_1#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"当时真的很谢谢你，要是没有你，毕娜和我一定已经……","en":"Thanks for saving me back then. Without you, both Pina and I wouldn't have made it.","ja":"あの時はありがとうございましたピナもあたしも、あなたがいなかったら、きっと……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_2#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"没有人知道之后会在这个世界遇上什么……所以我想好好把握当下。","en":"Since the future is so uncertain in this world, I want to cherish this moment.","ja":"この世界では、明日どうなるかもわからないから……今この瞬間を大切にしたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_3#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"我已经不想再跟别人组队了……讲这种话果然会让人觉得很任性吗？","en":"If I said I didn't want to join anyone else's party...would that be selfish of me?","ja":"もう、ほかの人とはパーティ組みたくない……なんてやっぱりわがままですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_4#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_4","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"或许我配不上你，可是……我的心意绝对没有半点虚假！","en":"I know I may not be the best match for you...but...I swear my feelings are genuine!","ja":"あたしじゃ、ふさわしくないかもしれないけど、でも……この気持ちは、絶対本物です!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_5#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_5","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"有你在身边我就能鼓起勇气。明天也想生存下去，像这样继续和你在一起……","en":"You always give me courage. Courage to survive another day, so that I can be with you...","ja":"あなたといると、勇気が出ます明日も生き延びて、またあなたとこうして一緒にいたいって……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_6#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_6","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"我想这里一定是《SAO》里最安全的地方，也是最能让人安心的地方。","en":"This must be the safest place in SAO. And also the most relaxing one.","ja":"ここは、きっと《SAO》で一番安全な場所ですねそして、一番安心できる場所です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_7#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_7","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"虽然被关在这里让人很痛苦，但能够遇见你……是我的宝贵回忆。","en":"As painful as our imprisonment is, meeting you here...is one of my most cherished memories.","ja":"閉じ込められちゃったのはつらいけど、でもあなたと出会えたのは……大切な思い出です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_8#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_8","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"毕娜说牠也想跟我们一起睡……但我请牠先忍耐一下了。","en":"Pina says she also wants to go to bed... I've been pushing her too hard.","ja":"ピナも一緒に寝たいって言ってるんですけど……我慢してもらっちゃいました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_sao_sleeping_9#originalText","id":"talk.vc.home_wait_silica_sao_sleeping_9","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"就算不说话，光是待在一起，也会觉得心情平静呢。","en":"We don't even have to talk. Just sharing space with you puts me at ease somehow.","ja":"話をしなくても、一緒にいるだけでなんだか気持ちが落ち着きます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_1#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我们相遇那天，你也温柔地摸了我的头呢。就像现在这样……","en":"I remember you gently patted my head the day we met, too. Just like right now...","ja":"出会った日も、優しく頭をなでてくれましたよねちょうど、今みたいに……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_2#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"别担心，我不会再哭了。有毕娜和你陪在身边，我不要紧的。","en":"Don't worry, I won't cry anymore. I'll be all right. I've got both you and Pina on my side.","ja":"大丈夫です、もう泣きませんピナもあなたもいてくれるからあたしは大丈夫です"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_3#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那个……你觉得这种发型如何？看起来会不会有点孩子气啊……","en":"So, um...what do you think of my hairstyle? I'm not sure... Maybe it's too childish?","ja":"あの……こういう髪型ってどうですか?ちょっと、子どもっぽいかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_4#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"伦、伦理规范有规定，再继续下去的话……会越界的。","en":"D-Due to my personal moral code... once you cross that line, there's no turning back.","ja":"り、倫理コードがあるからそれ以上は……後戻りできなくなっちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_5#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"被你这样摸着感觉很安心，让我有点想睡了……","en":"I love being gently stroked like that. It's very reassuring. And it's making me a little sleepy...","ja":"そうやってなでてもらうとすごく安心できますなんだか眠くなっちゃう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_6#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"可以……牵着手吗？感觉这样牵着手睡觉，就不会做恶梦了……","en":"May I...hold your hand? I just think it might help keep the nightmares at bay.","ja":"手……つないでもいいですか?こうやって、つないだまま寝たら怖い夢を見ずにすみそうで……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_7#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你、你要那么做的话，那我……就把你当成抱枕来抱！","en":"W-Well, two can play at that game. Now...you're my body pillow!","ja":"そ、そんなことするならあたしだって……あなたを抱き枕にしちゃいます!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_sao_sleeping_8#originalText","id":"talk.vc.home_touch_silica_sao_sleeping_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"……直接把我拥入怀里也没关系，请用力抱紧我……","en":"It's all right...we can stay close like this. Hug me tight, while you're at it.","ja":"……このまま、抱き寄せてもいいですよ。思いっきりギュッてしてください……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_1#originalText","id":"talk.vc.home_time_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"早安。那个，今天……你可以就这样陪着我吗？","en":"Good morning. So, um...can we just spend the whole day together?","ja":"おはようございますあの、今日は……このまま一緒にいてくれますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_2#originalText","id":"talk.vc.home_time_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"没想到《艾恩葛朗特》的早晨会让人感到如此神清气爽……是因为有你在身边吧？","en":"Mornings in Aincrad never felt this good before... It must be because you're here.","ja":"《アインクラッド》の朝がこんなに気持ちいいなんて……あなたと一緒にいるおかげですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_4#originalText","id":"talk.vc.home_time_silica_sao_sleeping_4","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"就算在游戏里，还是会肚子饿呢。要不要去吃点什么？","en":"It's funny how we still get hungry, even though we're in a VR game. Want to get something to eat?","ja":"ゲームの中でもお腹は空いちゃうんですよねなにか、食べに行きますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_5#originalText","id":"talk.vc.home_time_silica_sao_sleeping_5","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"虽然知道该起床了……但这里实在太幸福了……","en":"I keep thinking I really should get out of bed...but it just feels so cozy.","ja":"もう起きなきゃってずっと思ってるんですけど……ここが幸せすぎて……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_7#originalText","id":"talk.vc.home_time_silica_sao_sleeping_7","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"《艾恩葛朗特》入夜后虽然很吓人，但只要有你在身边，我就天不怕地不怕！","en":"I used to find nights in Aincrad terrifying. But with you by my side, I'm not scared anymore!","ja":"《アインクラッド》の夜は怖かったけど、あなたと一緒なら怖くありません!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_8#originalText","id":"talk.vc.home_time_silica_sao_sleeping_8","speaker":{"cn":"西莉卡","ja":"シリカ"},"text":{"cn":"今天要好好睡一整天，对吧？你平时那么努力地攻略，偶尔也该休息一下。","en":"You were supposed to sleep all day, remember? Your raids will be more successful if you're well rested.","ja":"今日は一日中寝る日、でしたね攻略頑張ってるんですからたまにはお休みしてください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_10#originalText","id":"talk.vc.home_time_silica_sao_sleeping_10","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"对不起，吵醒你了。毕娜跑来撒娇，我摸了牠一下。","en":"Sorry I woke you. Pina was acting needy so I was just petting her.","ja":"すみません、起こしちゃってピナが甘えてきたのでなでてあげてました"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_sao_sleeping_11#originalText","id":"talk.vc.home_time_silica_sao_sleeping_11","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"半夜醒来发现你就躺在身边……起初我还以为自己是在做梦呢。","en":"Waking in the middle of the night next to you felt like a dream at first...but it's really you.","ja":"夜中に目が覚めて、隣にあなたがいるなんて……最初、夢かと思っちゃいました"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_sao_sleeping_1#originalText","id":"talk.vc.home_day_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天开始又要攻略了吗？那个，请一定要小心喔。然后，要平安回来……","en":"Another raid today? Please... be careful? And when you're done... come back here.","ja":"今日からまた攻略ですか?あの、本当に気をつけてくださいそしてまた、ここに……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_sao_sleeping_2#originalText","id":"talk.vc.home_day_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"能像这样每天看见你的脸……让我很安心，也很高兴。","en":"I love seeing you every day like this. I just feel so...relaxed.","ja":"こうして、毎日あなたのお顔が見られて……ホッとするし、うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_sao_sleeping_3#originalText","id":"talk.vc.home_day_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天请好好休息吧。只要是我能做的，不管什么事我都愿意帮忙！","en":"Rest well today. If there's anything I can do to help, please let me know!","ja":"今日はゆっくり休んでくださいあたしにできることがあれば何でもお手伝いしますから!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_sao_sleeping_4#originalText","id":"talk.vc.home_day_silica_sao_sleeping_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"有好好休息了吗？那就好。明天开始也请记得不要太勉强自己……","en":"Did you have a restful day? I hope so. Try to go easier on yourself in the future.","ja":"ゆっくり体は休まりましたか?ならよかったです。明日からも無理はしないでください……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_1#originalText","id":"talk.vc.home_event_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"没想到能在游戏里过新年……感觉真是不可思议。","en":"Look at us, celebrating New Year's inside a game! It just feels... rather surreal.","ja":"ゲームの中でお正月を迎えるなんて……なんだか不思議な気分です"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_2#originalText","id":"talk.vc.home_event_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"只要在节分成功将鬼赶跑，我想大家一定就能一起成功攻略《SAO》的！","en":"If we exorcise all the devils on Setsubun, clearing SAO will be easy, won't it?","ja":"節分で鬼を追い払ったらきっとみんなで《SAO》をクリアできますよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_3#originalText","id":"talk.vc.home_event_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"情人节能像这样待在你身边……我真的想都没想过。","en":"Look at me, spending Valentine's Day with you...I never imagined it could happen.","ja":"バレンタインに、こうやって側にいられるなんて……思ってもみませんでした"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_4#originalText","id":"talk.vc.home_event_silica_sao_sleeping_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我看到镇上有在卖像是雏米果的点心。你瞧，是不是做得很精致呢？","en":"They were selling some sweets that looked like Hina dolls in town. See? Well-made, aren't they?","ja":"ひなあられみたいなお菓子が街で売られてました。ほら、すごくよくできてますよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_5#originalText","id":"talk.vc.home_event_silica_sao_sleeping_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不用给我回礼。只要你像这样陪在我身边，我就心满意足了。","en":"I don't need a White Day gift. Just being with you like this is chocolate for the soul!","ja":"お返しはいらないですこうして、あなたが側にいてくれるだけで、お腹いっぱいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_6#originalText","id":"talk.vc.home_event_silica_sao_sleeping_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算是愚人节，我也绝对不会怀疑你的！","en":"Even though it's April Fools' Day, I still won't distrust you!","ja":"エイプリルフールでもあなたのことだけは疑ったりしません!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_7#originalText","id":"talk.vc.home_event_silica_sao_sleeping_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"黄金周大家都放假了，我们也放轻松好好休息吧。","en":"Everyone else is taking Golden Week off. We should take it easy, too.","ja":"ゴールデンウィークは、みんなお休みしてます。あたしたちもゆっくりお休みしましょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_8#originalText","id":"talk.vc.home_event_silica_sao_sleeping_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"明明是在游戏里，下雨天一样能感受到空气的湿润呢。你的肌肤也黏答答的。","en":"I'm surprised by how realistic they got the rain moisture in this game. Your skin is glowing.","ja":"ゲームの中なのに、雨の日は空気が湿って感じますねあなたの肌も、しっとりしてます"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_9#originalText","id":"talk.vc.home_event_silica_sao_sleeping_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算你去了银河的另一端，我也会乘着毕娜去见你的。","en":"Even if you disappeared to the other side of the galaxy, I would fly on Pina to see you.","ja":"もし、あなたが天の川の向こうに行っちゃってもピナに乗って、会いに行きます"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_10#originalText","id":"talk.vc.home_event_silica_sao_sleeping_10","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"要是能从这里逃出去，我想跟你一起参加祭典。好想跟你一起吃苹果糖喔……","en":"It's summer festival season... If we could slip away, I'd love to go eat candied apples with you.","ja":"お祭り、もしここから出られたら一緒に行きたいですふたりでリンゴ飴、食べたいな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_11#originalText","id":"talk.vc.home_event_silica_sao_sleeping_11","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如果是在现实世界，我一定会觉得明天要上学很烦，但现在……我只希望能赶快再为这件事烦恼。","en":"If we were in the real world, I'd be dreading school tomorrow... But now, I wish I could go.","ja":"現実だったら、きっと明日からの学校が憂鬱だったと思いますでも今は……早くそう思いたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_12#originalText","id":"talk.vc.home_event_silica_sao_sleeping_12","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算是在这个世界，月亮还是很美。说不定……是因为跟你在一起，所以感受特别明显。","en":"Even in this world, the moon is so pretty. Maybe it's extra pretty because...you're here with me.","ja":"この世界でも、やっぱりお月様はきれいです。あなたと一緒だから特に……かも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_13#originalText","id":"talk.vc.home_event_silica_sao_sleeping_13","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"Trick or Treat！不想被捣蛋的话……就请你保持这样别动。","en":"Trick or Treat! Rather... trick or stay with me.","ja":"トリックオアトリートいたずらされたくなければ……このままで、いてください"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_14#originalText","id":"talk.vc.home_event_silica_sao_sleeping_14","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那天，我的眼前一片黑暗……不过，现在不要紧了，因为有你和毕娜陪着我。","en":"That day, I felt so lost and alone. But I'm okay now, because I have you and Pina.","ja":"あの日は、目の前が真っ暗になって……でも、今は平気ですあなたとピナが一緒だから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_sao_sleeping_15#originalText","id":"talk.vc.home_event_silica_sao_sleeping_15","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"圣诞节到了，我准备了礼物要送你……这是我的心意！","en":"I got you a Christmas present... Think of this as, my feelings in a box!","ja":"クリスマスだから、プレゼントを用意してきたんです……あたしの、気持ちです!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_sao_sleeping_2#originalText","id":"talk.vc.home_bd_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我以前从来不觉得在《SAO》中过生日是件开心的事。但现在，我真的……非常高兴。","en":"I used to resent having a birthday inside SAO. But now...I'm really grateful for it.","ja":"《SAO》の中で誕生日を迎えてもうれしくないって思ってたんですでも、今はすごく……うれしい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_sao_sleeping_3#originalText","id":"talk.vc.home_bd_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"祝你生日快乐。那个，你愿意在这么重要的日子和我在一起……我好开心。","en":"Happy Birthday! It's really, um... an honor to celebrate such a special day with you.","ja":"お誕生日、おめでとうございますあの、そんな大事な日に一緒にいてくれて……うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_sao_sleeping_6#originalText","id":"talk.vc.home_bd_silica_sao_sleeping_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是亚丝娜的生日呢……那个……我方便也去祝贺吗？","en":"It's Asuna's birthday today. So, um...do you think I should get her a present?","ja":"アスナさんのお誕生日なんですねあの……あたしからもお祝いあげてもいいでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_sao_sleeping_14#originalText","id":"talk.vc.home_bd_silica_sao_sleeping_14","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是莉兹姊姊的生日，我们到莉兹姊姊开的店举办派对吧！","en":"It's Liz's birthday today. Let's have a party at her shop!","ja":"今日はリズさんのお誕生日ですリズさんのお店で、パーティーやりましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_sao_sleeping_1#originalText","id":"talk.vc.home_etc_silica_sao_sleeping_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你今天也顺利结束攻略，平安回来了呢。真是太好了……","en":"You came back from another day of raids in one piece. What a relief.","ja":"今日も無事に、攻略から帰ってきてくれたんですねよかった……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_sao_sleeping_2#originalText","id":"talk.vc.home_etc_silica_sao_sleeping_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"有礼物送到了呢。里面说不定也有我要送给你的……","en":"You've received a gift. There might be one from me, too.","ja":"贈り物が来てますねあたしの贈った物もあるかもです……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_silica_sao_sleeping_3#originalText","id":"talk.vc.home_etc_silica_sao_sleeping_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你又要去攻略了呀。如果我再变强一点，也想要去帮忙……","en":"Off to another raid, I see. I'd love to help you someday, once I've gotten stronger.","ja":"また攻略に行くんですねあたしも、もっと強くなったらお手伝いしたいです……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"好像到现在还是有人觉得我们两个都是女生。也对啦，你的外表难免会被误会。","en":"Some people still think we're both girls. Well, when you look like that, who could blame them?","ja":"今でも、私たちふたりとも女の子だって思ってる人がいるみたい。まぁその見た目ならしょうがないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"《ALO》虽然也很有趣，但回来这边闻到火药的气味，就让我有种返家的感觉。","en":"ALO is fun and all, but nothing gives me the \"I'm home\" vibe more than the smell of gunpowder.","ja":"《ALO》も楽しいけどこっちに戻って火薬の匂いを嗅ぐと帰ってきたって感じがするの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"シノン"},"text":{"cn":"欸，你也在这边买栋房子啦，这样就能随意来往了不是吗？……当作是我跟你的家也无妨。","en":"Just buy a house here already. Then you can pop in whenever... We can share, if you want.","ja":"ね、こっちでもハウスを買いなさいよそうすれば、気軽に来られるでしょ……私と共同の家でもいいから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"シノン"},"text":{"cn":"这个世界好像也有和世界本身的设置有关的任务，像是毁灭的文明等等。找个时间，我们一起去解任务吧。","en":"This world also seems to have quests based off lost civilizations. We should go on one together sometime.","ja":"この世界にも、滅んだ文明とか、世界設定に絡んだクエストがあるみたいいつか、ふたりでやりましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_5#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不管再怎么提升技能等级，我都只会使用这把枪。我想自己永远都不会有抛下它的一天。","en":"I don't care how high I level up, I'm still using this gun. I couldn't bear to lose her.","ja":"どんなにスキルアップしても私はずっとこの銃を使うわ手放すことは、きっとないと思う"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_6#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽然在现实世界会有点害羞，但是在这个世界的话，坐在机车后座感觉也很不错呢。","en":"I feel kind of awkward doing it IRL, but sharing a bike here in this world isn't half bad.","ja":"現実ではちょっと恥ずかしいけどこの世界でだったら、バイクの後ろに乗せてもらうのも悪くないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_7#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"下一届《BoB》要不要一起报名？当然这次没有要并肩作战，我要跟你正面对决。","en":"Wanna enter the next BoB with me? Not as a team, of course. As opponents. And I'll kick your butt.","ja":"次の《BoB》、ふたりで出てみない?もちろん、今回は共闘なんかせず正面から戦うわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_8#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"宇宙战舰的装甲板？哪里找得到这种材料啊？不过你需要的话，我也会帮忙找的。","en":"You want a spaceship armor plate? Where do we even find that? Well, I'll help you look if you need it.","ja":"宇宙戦艦の装甲板?そんな素材どこにあるのかしらでも必要なら、私も手伝うわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_ggo_2nd_anniv_9#originalText","id":"talk.vc.home_wait_sinon_ggo_2nd_anniv_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"喂喂～？怎么了，在那边发呆？你要是累了，要不要休息一下？","en":"Hellooo? Anybody home? If you're tired, wanna take a break?","ja":"もしもーし?どうしたの、ぼーっとして疲れてるのなら、休憩する?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"眼睛可是狙击手的生命，请不要随意乱碰，除非你想被我折断手指。","en":"A sniper's eyes are her lifeline. So hands off. Next time, I'll break your fingers.","ja":"目はスナイパーの命なんだから気軽に触らないでちょうだい指を折られたくなかったらね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……真是的，你为什么这么想摸我的头发啊？也让我摸摸你的，就当作是回敬你。","en":"Jeez...why are you so obsessed with my hair? I'm going to touch yours back if you don't stop.","ja":"……もう、どうしてそんなに髪を触りたがるのかしらお返しに、あんたのも触らせなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"喂、喂！？突然摸我的嘴唇……你想做……什么？","en":"Uh, excuse me?! Why're you touching my lips...? What are you...trying to do here?","ja":"ちょ、ちょっと!?いきなり唇を触って……どういうつもり……なの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我会穿成这样，是因为重视灵活度，才不是为了要让你摸呢。","en":"When I chose this outfit, I was prioritizing comfort and mobility— not touchability. Got it?","ja":"この格好は、動きやすさを優先してるの。あんたに触らせるためなんかじゃないんだからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_5#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"搞、搞不好有人在旁边看耶！唉，为什么男生总想做这种事啊……","en":"D-Dude, somebody might see! Argh, why are boys so touchy-feely...","ja":"だ、誰か見てるかもしれないでしょ!はあ、もう男ってどうしてこんなことしたがるんだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_6#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我、我会心跳加速还不是因为你对我做那种事！……别再让我继续说下去了。","en":"M-My heartbeat is so fast because of you... Don't make me say more.","ja":"し、心臓の鼓動が速いのはあんたがそうやってしてるからよ……これ以上は、言わせないで"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_7#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你碰那种地方可要小心，别一个糊涂把手榴弹的保险销给拔掉了喔。","en":"I just hope you don't accidentally pull out a grenade pin and blow yourself up while you're fumbling.","ja":"そんなところいじって、うっかりグレネードのピンを抜いたりしないでよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_ggo_2nd_anniv_8#originalText","id":"talk.vc.home_touch_sinon_ggo_2nd_anniv_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"真是的，你再不收敛点，我也要开始反击了哦……？看我把你绑起来搔痒！","en":"Okay, if you don't cut that out, I'm pulling out the big guns? And by that, I mean tying you up and tickling you!","ja":"もう、いい加減にしないとこっちだって反撃するからね……?縛り上げてくすぐってやるんだから!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……早。你为什么偏偏挑今天早起啊？我的睡脸……你看见了？","en":"Hey... Why'd you have to wake up so early today of all days? You didn't...see me asleep, did you?","ja":"……おはようどうして、今日に限って早起きなのよ私の寝顔……見た?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"好了，快起床啦，贪睡鬼。不是说好今天一整天都要陪我吗？","en":"Come on, sleepy head, wake up. Remember? You said you'd hang out with me today.","ja":"ほら、起きて寝ぼすけさん今日は一日、私に付き合うって約束したでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……现在还不用起床吧？你自己也一副还想睡的样子，我们去睡回笼觉吧。","en":"I don't think we have to get up yet. You look just as sleepy as me. Let's go back to bed.","ja":"まだ……起きなくていいんじゃない?あんただって、眠そうな顔してるわよ二度寝、しちゃいましょ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"VR跟现实不一样，不需要担心晒黑，可以轻松外出呢。","en":"Since I don't have to worry about sunburns in VR, I can go outside worry-free.","ja":"リアルと違って、VRの中だと日焼けの心配がないから外出するのも気が楽ね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_5#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天就到店里逛逛好了。你要不要偶尔也保养一下枪枝？辅助武器也是很重要的。","en":"Wanna go shopping? It wouldn't hurt you to get yourself a gun, either. Sub-weapons are useful.","ja":"今日は、お店を見て回ろうかなあんたもたまには銃の手入れしたら?サブウェポンも重要なのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_6#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"白天虽然容易瞄准敌人，但我方也会暴露在同样的风险下。要狙击的话，我还是偏好晚上。","en":"It's easier to catch enemies in the daytime, but the same applies to them. That's why I prefer night.","ja":"昼間は敵を捕捉しやすいけどこっちにも同じリスクがある狙撃するなら、私は夜の方が好き"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_7#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你要赌博是无妨，但你总是叫人看了心惊胆战啊。每次都只会唬人而已。","en":"Risk-taking can pay off, but you give me heart palpitations. You really fly by the seat of your pants.","ja":"ギャンブルやるのはいいけどあんたを見てるとハラハラするわいつもはったりばかりじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_8#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你真的吃得很香呢。跟你一起吃饭，总会害我也忘了要节制。","en":"You do love your food, don't you? Whenever we eat together, I have to stop myself from pigging out.","ja":"本当においしそうに食べるわね一緒に食事してると、私までついつい食べ過ぎちゃうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_9#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我在现实虽然晚上不敢出门，但在这个世界就没问题。因为这里的黑暗，是站在我这边的。","en":"Walking alone at night is scary IRL, but I feel safe in this world. The darkness is my ally here.","ja":"リアルだと、夜に出歩くのは怖いけどこの世界なら大丈夫なのここの暗闇は、私の味方だから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_10#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"想睡了？抱歉，让你陪我到这么晚，我们去睡吧。","en":"Are you tired? Sorry I kept you up. Let's turn in.","ja":"眠くなってきた?ごめんね、付き合わせちゃってそろそろ寝ましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_11#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"夜晚静谧的空气总让我感到心安，虽然这可能是因为跟你独处的关系。","en":"The quiet night air always quiets the noise in my head. Though part of that might have to do with you.","ja":"夜の静かな空気は心が落ち着くわふたりでいるせいかもしれないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_ggo_2nd_anniv_12#originalText","id":"talk.vc.home_time_sinon_ggo_2nd_anniv_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"半夜跟你一起走在外面，会感觉彼此的距离特别近。是因为看不清周围的景色吗？","en":"When we walk outside late at night, I feel closer to you. Maybe it's because I can't see anything else.","ja":"深夜、ふたりで外を歩いているとなんだか距離が近く感じる周りが見えないせいかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_day_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"对耶，今天是星期一。待在游戏里面，一不小心就会忘掉今天是星期几呢。","en":"Oh, it's Monday. I always lose track of the day when I'm in-game.","ja":"そっか、今日は月曜日ねゲームの中にいると、つい曜日のことを失念しちゃうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_day_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"卖力打工是无妨，但你要注意别太勉强自己了，明白吗？","en":"I admire your work ethic, but go easy on yourself, okay?","ja":"バイト頑張るのもいいけどくれぐれも無理はしないことわかった?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_day_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"偶尔悠哉放个假也很不错呢。正好也有个适合的聊天对象。","en":"A lazy day off is a good thing. And it just so happens you've got someone cool to talk to.","ja":"たまには、のんびりなお休みも悪くないわねちょうどいいお喋り相手もいるし"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_day_sinon_ggo_2nd_anniv_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这周每天都过得很开心呢。嗯，可能多少也是因为一直跟你待在一起吧。","en":"I had fun all week. Well, guess I owe you some credit for that.","ja":"今週は、ずっと楽しかったわま、あんたが一緒だったからっていうのも、少しはあるかもね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我几乎没玩过什么新年的游戏。像板羽球之类的活动，我有点感兴趣。","en":"I never really played New Year's games before. Like badminton. Sounds like fun, though.","ja":"お正月の遊びって、あんまりやったことないの羽根つきとか、ちょっと興味あるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"为了平安地度过今年，要好好撒豆，祛除灾厄才行呢。","en":"We'd better throw lots of beans to ward off those evil spirits this year.","ja":"今年は平穏に過ごせるようにちゃんと豆まきして厄を祓わないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"在这边也给你吧。来，这是情人节巧克力。我在现实也有准备，别担心。","en":"Here's your in-game Valentine. I've got chocolate for you IRL, too, of course.","ja":"一応、こっちでもねはい、バレンタインのチョコリアルでもちゃんと用意してあるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我平时虽然不太喝甜酒，但偶尔喝一下还挺不错呢。尤其是在欣赏女儿节娃娃的时候。","en":"I don't drink much amazake, but I like it sometimes. Especially for Hinamatsuri. Ambiance, you know?","ja":"甘酒ってあんまり飲まないけどたまに飲むと、意外とおいしいわねおひな様を見ながらだと、余計にね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_5#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"咦？情人节的回礼？你在现实明明也送了……我真的可以收吗？我真的很高兴，谢谢你。","en":"Uh, another White Day gift? You already gave me one IRL... But thanks. That's so sweet.","ja":"え、バレンタインのお返し?リアルでももらったのに……いいの?うれしい、ありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_6#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我要不要也用用看光剑呢……说说而已。不过，带一把当护身符似乎也不错。","en":" Maybe I'll try out a Photon Sword... Yeah, no. Though I'll probably  carry one for insurance.","ja":"私も光剣使ってみようかな……なんてね。お守りに、1本持っておくのはいいかもね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_7#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"连假期间到哪都是人呢。我们找个没人的地方，一起悠哉打怪吧。","en":"It gets so crowded here during the long break. Let's go find a quiet place to hunt.","ja":"連休中はどこも混んでるわね人がいないスポットで、ふたりでのんびり狩りでもしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_8#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"在梅雨期间看到太阳就会很开心呢。虽然平时都觉得很刺眼，高兴不太起来就是了。","en":"I always love the little breaks in the rain during rainy season. Though the sun's too bright for me, normally.","ja":"梅雨の間は、晴れ間がうれしくなるわ普段は、日差しがきつくてあんまり喜べないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_9#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"难得可以待在一块，我们今天就一起欣赏银河吧。希望晚上会放晴。","en":"Since we're both here, let's go look for Hikoboshi and Orihime in the sky. Hope it's a clear night.","ja":"せっかく一緒にいるんだから今日はふたりで天の川を見ましょうか夜、晴れるといいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_10#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"欸，要不要放烟火？我很喜欢那种稍纵即逝的感觉，还有扑鼻而来的火药味。","en":"Wanna light some fireworks? I love how fleeting they are... and the smell of gunpowder.","ja":"ね、花火やらない?あの儚い感じと、ふわっと香る火薬の匂いが好きなの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_11#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"结果这整个暑假，我们都一直在玩《GGO》呢。留下了非常棒的回忆。","en":"We wound up playing GGO all summer long, huh? We made some good memories.","ja":"結局夏休みはずっと一緒に《GGO》してたわねすごくいい思い出になったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_12#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不知不觉就到月亮升起的时间了。虽然还想再玩一下，但我们差不多该回去那边了。","en":"The moon's up already. I'd love to play longer, but maybe we should head back.","ja":"いつの間にか、月が上がる時間ねもうちょっと遊びたいけどそろそろ向こうに戻りましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_13#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_13","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"有不少人在万圣节把自己的枪和装备弄得五颜六色呢。我就……免了吧。","en":"Lots of people dress up their guns and body gear for Halloween. But...I think I'll pass.","ja":"ハロウィンで、銃や装備をカラフルにしてる人が多いわね私は……ちょっと遠慮しとく"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_ggo_2nd_anniv_15#originalText","id":"talk.vc.home_event_sinon_ggo_2nd_anniv_15","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"圣诞快乐。呵呵，你扮起圣诞老人非常合适喔。","en":"Merry Christmas. Aww, you look cute in that Santa suit.","ja":"メリークリスマスふふ、サンタさんの格好すごく似合ってるわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_season_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"以前虽然不了解原因，但我现在慢慢能体会春天为何被叫做离别的季节了。","en":"I used to be puzzled when folks said spring was \"a season of farewells.\" But now I get it.","ja":"昔はよくわからなかったけど今は「春が別れの季節」って言われる意味がわかってきたわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_season_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我虽然很耐热，但很不喜欢流汗搞得全身黏答答的。真希望天气能早点转凉。","en":"Heat, I can deal with. But sweat? Get me an AC, quick.","ja":"暑いのは我慢できるけど体が汗でべたつくのは無理早く涼しくなってほしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_season_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"差不多快到手指会冻僵的季节了。不好好保养手部的话，会影响到狙击的精准度。","en":"It's dry skin season. Better take good care of those nails so it won't throw off my sniping.","ja":"そろそろ、指先がかじかむ季節ねちゃんとケアしないとスナイピングに影響が出ちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_ggo_2nd_anniv_4#originalText","id":"talk.vc.home_season_sinon_ggo_2nd_anniv_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"在这个季节骑机车，你不冷吗？来，这条围巾给你围着，你要是感冒我会很困扰的。","en":"Isn't fall a bit cold for a bike? Here, use this scarf. Wouldn't want you catching cold.","ja":"この季節にバイクって、寒くないの?ほら、このマフラー使って風邪を引かれても困るから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"谢谢你的祝福。能和你一起庆祝生日，对我而言就是最棒的礼物了。","en":"Thanks. Spending my birthday with you is the best present I could ask for.","ja":"ありがとう、祝ってくれてこうしてふたりで祝えるのが私には最高のプレゼントになるの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"桐人今天生日……我约他出来……没问题吗？可能的话，我想和他两个人单独过。","en":"Should I invite...Kirito over on his birthday? I wanna spend the day with him, if possible...","ja":"キリトの誕生日……誘っても……大丈夫かしらできれば、ふたりで過ごしたいの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_5#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"爱丽丝要是来《GGO》，我就能送她许多东西了，但这好像有点难实现呢。","en":"If Alice could come to GGO, there's all sorts of gifts I could give her... but it looks like that's not happening.","ja":"アリスが《GGO》に来られたらいろいろ贈ってあげられるんだけどそれはちょっと難しそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_6#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"亚丝娜生日这天，我们女生自己办了小小的派对。至于在聊什么……就不告诉你了。","en":"Asuna and I are having a chill day of girl-talk together for her birthday... and you're not invited.","ja":"アスナの誕生日には、女同士でささやかなお祝いをしてるの何を話してるかは……秘密よ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_7#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"莉法今天生日，你要好好为她庆祝喔，她收到哥哥送的礼物一定会很高兴的。","en":"Make sure you get Leafa something for her birthday. I know she'd love a present from her cool big brother.","ja":"リーファの誕生日、ちゃんとお祝いしてあげてね。兄妹からの贈り物って、きっとうれしいから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_9#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天是有纪的庆生会，我们差不多该出门了。礼物拿好了吗？","en":"Should we head out to Yuuki's birthday party now? Do you have her present?","ja":"ユウキの誕生日会、そろそろ出かけましょうかプレゼントはちゃんと持った?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_14#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_14","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"莉兹会想要什么东西啊？我的装备平常也是她制作的，我想好好祝贺她。","en":"What do you think Liz would like? Since she makes all my equipment, I want to get her something nice.","ja":"リズってどんなものが欲しいのかしら装備も作ってもらってるしちゃんとお祝いしたいの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_ggo_2nd_anniv_15#originalText","id":"talk.vc.home_bd_sinon_ggo_2nd_anniv_15","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"真希望西莉卡可以来玩《GGO》，我想送她一把大口径的枪。","en":"I'd love to drag Silica to GGO and give her a high-caliber firearm for her birthday.","ja":"シリカには、ぜひ《GGO》に来てもらって、大口径の銃をプレゼントしたいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_ggo_2nd_anniv_1#originalText","id":"talk.vc.home_etc_sinon_ggo_2nd_anniv_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"完成使命，辛苦了！你的技术果然不是盖的，我也觉得受益匪浅。","en":"Congrats on the mission. Great form, as always. I should take notes.","ja":"ミッションクリア、お疲れさまさすがに手際がいいわね私も参考にさせてもらうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_ggo_2nd_anniv_2#originalText","id":"talk.vc.home_etc_sinon_ggo_2nd_anniv_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"记得时常检查礼物盒。要是有重要的东西却没发现，不就糟了吗？","en":"Always check your gifts. Wouldn't want to lose out on something awesome.","ja":"ギフトはちゃんとチェックすること大事なものがあったら大変でしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sinon_ggo_2nd_anniv_3#originalText","id":"talk.vc.home_etc_sinon_ggo_2nd_anniv_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"下个使命你看过了吗？感觉我们不需要费多少力气就能完成呢。","en":"Did you check out the next mission yet? I think we've got this one in the bag.","ja":"次のミッション、確認した?私たちなら、それほど苦労せずにクリアできそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_os_1#originalText","id":"talk.vc.home_wait_sinon_os_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"Ordinal Scale的战场范围有限，所以很难拉开距离来瞄准敌人。","en":"The battlefield area in Ordinal Scale is pretty limited so I can't aim too far away.","ja":"オーディナルスケールって戦場エリアが限られるからあんまり長距離で狙えないのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_os_2#originalText","id":"talk.vc.home_wait_sinon_os_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"将来会不会发售装有Augma的眼镜呢？","en":"I wonder if the Augma glasses have gone on sale?","ja":"オーグマーが一体になった眼鏡って発売されないのかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_os_1#originalText","id":"talk.vc.home_touch_sinon_os_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这里不是VR的世界，你注意一下你的举动好吗。","en":"This isn't the VR world so please try and keep yourself together.","ja":"ここはVRの中じゃないんだから少しは自重しなさいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_os_4#originalText","id":"talk.vc.home_touch_sinon_os_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"等、等一下！如果在这边的世界做了那样的事，肯定就是犯法了啊。","en":"W-wait! If you did that in this world then it really would be considered a crime!","ja":"ちょ、ちょっと!こっちの世界でそれやったら本当に犯罪だからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_os_5#originalText","id":"talk.vc.home_touch_sinon_os_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这是AR的枪，所以也没办法交给你。","en":"Since this is an AR gun, I can't just pass it along to you.","ja":"これはARの銃だからあんたに渡すことはできないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_os_1#originalText","id":"talk.vc.home_time_sinon_os_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"早安。一大早就怎么了？难道有Ordinal Scale的战斗吗？","en":"Morning. Why are you up this early? Was there another battle on Ordinal Scale?","ja":"おはよう。どうしたの、朝から?またオーディナルスケールのバトルでもあるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_os_4#originalText","id":"talk.vc.home_time_sinon_os_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"明明是AR，但枪的质感却跟真的一模一样……","en":"Even though we're in an AR, the texture of this gun is identical to the real thing...","ja":"ARなのに、銃の質感は本物そっくりなのね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_os_7#originalText","id":"talk.vc.home_time_sinon_os_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"已经这个时间了。一直显示着时间，总觉得很悠闲呢。","en":"Time sure does fly. It doesn't help that the time is always displayed neither.","ja":"もうこんな時間なんだ常に時間が表示されてるってなんだかせわしないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_os_10#originalText","id":"talk.vc.home_time_sinon_os_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"原来Ordinal Scale深夜也会运作啊。","en":"Even in the middle of the night you're on Ordinal Scale, huh?","ja":"こんな夜中にもオーディナルスケールは動いてるのね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_os_1#originalText","id":"talk.vc.home_day_sinon_os_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"从星期一开始就可以像这样在现实见面，感觉也不坏呢。","en":"Being able to meet in the real world like this starting on Mondays doesn't seem too bad.","ja":"月曜からこうやって現実で会えるのは、なかなか悪くないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_os_2#originalText","id":"talk.vc.home_day_sinon_os_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"戴着Augma骑车视野不会变窄吗？","en":"Wouldn't riding a bike with the Augma on lower your field of vision?","ja":"オーグマー着けたままバイクに乗るのって視界が狭くならないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_os_3#originalText","id":"talk.vc.home_day_sinon_os_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"听说大家在放假的时候都在玩Ordinal Scale喔。","en":"Looks like everyone plays Ordinal Scale, even on holidays.","ja":"休みの日は、みんなオーディナルスケールプレイしているみたいね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_os_4#originalText","id":"talk.vc.home_day_sinon_os_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"因为放假就会很开心，所以明天也能继续努力。这个想法就这样不断的重复。","en":"It's because holidays are fun that gives us strength for tomorrow! That's how the cycle works.","ja":"休みが楽しいから、また明日も頑張れるずっとこれの繰り返しね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_os_1#originalText","id":"talk.vc.home_season_sinon_os_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你看，你的脸上都有压痕了，你是戴着Augma午睡了吧？","en":"Hey! You have a mark on your face. You took a nap with the Augma on, didn't you?","ja":"ほら、顔に跡がついてるオーグマーを着けたまま昼寝したんでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_os_2#originalText","id":"talk.vc.home_season_sinon_os_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"只是看着Augma显示的温度感觉就已经出汗了。","en":"Just looking at the temperature displayed on Augma is enough to make me break a sweat.","ja":"オーグマーに表示されている気温を見るだけで、なんだか汗が出てくるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_os_3#originalText","id":"talk.vc.home_season_sinon_os_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"感觉有点秋天的味道。在VR世界很难会有这种感觉。","en":"Somehow, it smells like autumn. It's rare to experience something like that in a VR world. ","ja":"なんだか秋の匂いがするこれって、VRの世界だとなかなか感じられないわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_os_4#originalText","id":"talk.vc.home_season_sinon_os_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"在AR世界看的雪，总觉得很不可思议。比VR看到的更梦幻。","en":"Seeing snow in the AR world is a very weird sensation, isn't it? It looks dreamier than in VR worlds!","ja":"ARの世界で見る雪ってなんだか不思議な感じねVRよりも幻想的に見える"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_1#originalText","id":"talk.vc.home_sinon_real_newyear_wait_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"新年快乐，今年也多多指教。","en":"Happy New Year! Let's make it a good one.","ja":"明けましておめでとう今年もよろしく"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_2#originalText","id":"talk.vc.home_sinon_real_newyear_wait_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"机会难得，我们一起去参拜吧？我们就以新年的第一次求签来决一胜负吧。","en":"Since it's the New Year, why don't we go visit a shrine? We can go find out our luck!","ja":"折角だし初詣に行かない?年明け一発目の運試しで勝負よ"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_3#originalText","id":"talk.vc.home_sinon_real_newyear_wait_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"好了，今年又会被卷进什么事情呢？都已经跟你一起经历这么多了，以后也会跟着你一起的。","en":"I wonder what kind of things you might get caught up with this year? Whatever it is, I'll always be by your side!","ja":"さぁ、今年はどんな事件に巻き込まれるの? ここまできたら全部付き合ってやるわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_4#originalText","id":"talk.vc.home_sinon_real_newyear_wait_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"山茶花虽然有种凛然的感觉，却又有点难以捉摸吧。","en":"Camellias are dignified yet fragile.","ja":"椿って、凛としているのにどこか儚げよね"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_5#originalText","id":"talk.vc.home_sinon_real_newyear_wait_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……我才不是为了让你看才穿成这样的。","en":"...Don't get the idea that I wore this just to show you.","ja":"……別にあんたに見せるために着てきたわけじゃないから"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_real_newyear_wait_6#originalText","id":"talk.vc.home_sinon_real_newyear_wait_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"咦……漂、漂亮……！？啊啊……你是说和服喔……","en":"B-Beautiful...! I meant...the kimono of course...","ja":"えっ……き、綺麗……!?あ、あぁ……着物がね……"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_alo_swim_wait_1#originalText","id":"talk.vc.home_sinon_alo_swim_wait_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"哈啊～这么热，总觉得身体像是被火烧似的呢。","en":"Haaaaa... I should have known I'd get all burnt up in this heat!","ja":"はぁ、こう暑いとなんだか体が火照って仕方ないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_alo_swim_touch_1#originalText","id":"talk.vc.home_sinon_alo_swim_touch_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"如果是泳衣的话，很凉爽很棒呢！","en":"Bathing suits sure are breezy.","ja":"水着だと、涼しくていいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_alo_swim_touch_2#originalText","id":"talk.vc.home_sinon_alo_swim_touch_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"啊！你、你的手好冰呀。吓到我了……","en":"Kyaa! Y-Your hand is ice-cold! Watch where you're touching...","ja":"きゃっ!あ、あんたの手、冷たいわねびっくりしちゃった……"},"kind":"dialogue"},{"uid":"talk.vc.home_sinon_alo_swim_touch_3#originalText","id":"talk.vc.home_sinon_alo_swim_touch_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"喂、你！靠、靠太近了啦！","en":"Y-You're getting too close!","ja":"ちょ、ちょっとち、近寄りすぎよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1st_1#originalText","id":"talk.vc.home_wait_sinon_1st_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"「小诗诗」是亚丝娜带头开始喊的……等等，可别连你都这么喊喔！","en":"Asuna has started calling me \"Shino-non,\" but...don't you dare go calling me that!","ja":"「シノのん」ってアスナが呼び始めたんだけど……ってあんたまで呼ばないでよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1st_2#originalText","id":"talk.vc.home_wait_sinon_1st_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"最近我也越来越喜欢待在VR世界里了。比起以前更能够放松地游玩。","en":"I enjoy being in VR a lot more now. I'm much more comfortable than I used to be.","ja":"最近は、VRの世界にいるのも楽しくなってきたの前よりも気負わずにプレイできる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1st_3#originalText","id":"talk.vc.home_wait_sinon_1st_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你偶尔也用枪战斗看看吧。出乎意料地有趣喔。","en":"Why don't you try using a gun sometimes? It's actually quite a lot of fun.","ja":"あんたもたまには銃で戦ってみたら?案外楽しいものよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1st_4#originalText","id":"talk.vc.home_wait_sinon_1st_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我就是不擅长魔法呢。要是能变成像手榴弹那样的道具该有多好。","en":"I just can't get the hang of magic. I wish spells were like items. I miss grenades.","ja":"魔法ってどうも苦手なのグレネードみたく、アイテムになってくれたらいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1st_9#originalText","id":"talk.vc.home_wait_sinon_1st_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……真受不了，你还在睡？你也太能睡了吧！反倒令人佩服了。","en":"Asleep again? In a way, I'm almost impressed by how easily you can doze off.","ja":"……もう、また寝てるの?よくそれだけ眠れるわね逆に感心しちゃうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1st_1#originalText","id":"talk.vc.home_touch_sinon_1st_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"要不要戴眼镜看看？或许你也意外地适合戴眼镜喔。","en":"Wanna try on some glasses? They might actually suit you.","ja":"眼鏡、かけてみる?あんたも、案外似合うかもしれないわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1st_2#originalText","id":"talk.vc.home_touch_sinon_1st_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽然我有时也会羡慕长头发……不过我还是偏好这个长度呢。","en":"Sometimes I wish I had long hair...but I think my style suits me best.","ja":"長い髪に憧れることもあるけど……私はやっぱりこのくらいがいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1st_4#originalText","id":"talk.vc.home_touch_sinon_1st_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……别这样。","en":"Don't.","ja":"……やめて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1st_5#originalText","id":"talk.vc.home_touch_sinon_1st_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"碰那种地方有趣吗？男生真是的……","en":"You really get that big a kick out of touching me? Men...","ja":"そんなとこ触って楽しいの?まったく、男って……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1st_6#originalText","id":"talk.vc.home_touch_sinon_1st_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你应该没有把我的胸部跟谁做比较吧？","en":"You'd better not be comparing my chest with someone else's.","ja":"誰かの胸と比べてるんじゃないでしょうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_1st_1#originalText","id":"talk.vc.home_time_sinon_1st_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"以你而言算是早起了呢。那就准备出门吧，一整天能运用的时间更多了呢。","en":"You're sure up early. Wanna head out? There's a full day ripe for the picking.","ja":"あんたにしては早起きねなら、もう出かけましょうか一日が長く使えるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_1st_4#originalText","id":"talk.vc.home_time_sinon_1st_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你脸上写着肚子饿呢。那就稍微休息一下吧，食物也已经准备好啰。","en":"I can tell you're hungry. Why don't we take a break? I've got some food.","ja":"お腹が空いたって顔ねなら、少し休憩しましょうご飯も用意してあるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_1st_7#originalText","id":"talk.vc.home_time_sinon_1st_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"以前我会有点害怕晚上独自一人……但现在不会了，因为我有护身符。","en":"I used to be scared to be alone at night...but I'm okay now. I have an amulet to protect me.","ja":"夜ひとりになるのは、少し怖かったんだけど……今は大丈夫お守りがあるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_1st_10#originalText","id":"talk.vc.home_time_sinon_1st_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"跟你在一起，总会一不注意就熬夜了。呵呵，这是为什么呢？","en":"I always stay up all night when I'm with you. Hehe, wonder why?","ja":"あんたといると、つい夜更かししちゃうのよねふふ、どうしてかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_1st_1#originalText","id":"talk.vc.home_day_sinon_1st_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不能因为是星期一就摸鱼喔。我会好好盯着你的。","en":"Don't slack off just because it's Monday, okay? I'm watching you.","ja":"月曜だからってサボりはダメよちゃんと見張ってるから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_1st_2#originalText","id":"talk.vc.home_day_sinon_1st_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"同学都在问你的事，让我很困扰耶。真是的，都怪你那样子来我学校……","en":"Everyone at school won't stop bugging me about you. Did you really have to make a scene?","ja":"学校で、あんたのことを聞かれて困ってるのよまったく、あんな風に来るから……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_1st_3#originalText","id":"talk.vc.home_day_sinon_1st_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天难得想放慢脚步喘口气。一起来放松吧。","en":"I feel like taking it easy today. Let's chill together.","ja":"今日は久しぶりに、少しゆっくりしたい気分一緒にリラックスしましょ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_1st_4#originalText","id":"talk.vc.home_day_sinon_1st_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"快乐的时光总是过得特别快呢。虽然很舍不得，但差不多该睡了吧。","en":"Time flies when you're having fun, eh? I hate to kill the mood, but we should turn in.","ja":"楽しい時間はあっという間ね名残惜しいけど、そろそろ休みましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_1st_1#originalText","id":"talk.vc.home_season_sinon_1st_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"是新环境开始的季节呢。以前的我会感到害怕……可是现在甚至还有些期待呢。","en":"It's a season of new beginnings. This sort of thing used to scare me, but now I'm excited.","ja":"新しい環境が始まる季節ね以前は怖かったけど……今は少し楽しみなくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_1st_2#originalText","id":"talk.vc.home_season_sinon_1st_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"话说回来，天气好热啊。你老是穿得一身黑，热气不会闷在衣服里吗？","en":"Man, it's hot. Doesn't dressing in black all the time make you sweat like crazy?","ja":"それにしても暑いわねいつも黒い格好で熱がこもらないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_1st_3#originalText","id":"talk.vc.home_season_sinon_1st_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽说是食欲之秋，但也有个限度吧……你该克制一点。","en":"I know autumn is said to be the season for eating...but I think you're overdoing it.","ja":"食欲の秋って言っても限度があるでしょう……少しは加減しなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_1st_4#originalText","id":"talk.vc.home_season_sinon_1st_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"比起炎热，寒冷或许还好一点……啊，我是在讲狙击的事。","en":"I always prefer cold weather over hot... Oh, I mean, in the context of being a sniper.","ja":"暑いよりは、まだ寒い方が楽かな……あ、スナイピングの話だけど"},"kind":"dialogue"},{"uid":"talk.vc.home_sortiliena_swimsuit_wait_1#originalText","id":"talk.vc.home_sortiliena_swimsuit_wait_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽说是真的很凉爽……但露出的肌肤太多有点害羞啊。","en":"It sure is breezy... But I'm a bit embarrassed by how exposed I am...","ja":"確かに涼しいが……露出が多くて少し気恥ずかしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_sortiliena_swimsuit_touch_1#originalText","id":"talk.vc.home_sortiliena_swimsuit_touch_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"平时的日子里不知多久没将头发放下过了。怎么，你比较喜欢这样子吗？","en":"It's been awhile since I've let my hair down and just relaxed. What, you like it better this way?","ja":"髪を下ろして過ごすのは久しぶりだなんだ、お前はこの方が好きか?"},"kind":"dialogue"},{"uid":"talk.vc.home_sortiliena_swimsuit_touch_2#originalText","id":"talk.vc.home_sortiliena_swimsuit_touch_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你！再继续触碰的话我可不会放过你的喔！","en":"Stop that! Don't even think about laying another finger!","ja":"こらっ!それ以上触ったらただじゃおかないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sortiliena_1st_1#originalText","id":"talk.vc.home_wait_sortiliena_1st_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你送我的赛菲利雅花，我已经做成压花，好好地装饰起来了喔。","en":"I pressed the zephyria you gave me so that I can keep it as a decoration.","ja":"お前にもらったゼフィリアは押し花にしてちゃんと飾ってあるぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sortiliena_1st_2#originalText","id":"talk.vc.home_wait_sortiliena_1st_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你的身边有不少跟你一样个性独特的人呢……虽然女性占大多数。","en":"You seem to surround yourself with like-minded individuals... most of whom are female.","ja":"お前の周りも、お前と同じく個性的な人間が多いのだな……女性ばかりだが"},"kind":"dialogue"}]};
